		["The Twilight's Hammer dig fills the north-west corner: tablet fragments lie on the ground and the Dust Stormers and Desert Rumblers carry them too. Every cultist can drop an {item:20404}: keep twenty, ten for {npc:15306} and ten for {npc:15194} later."] = "Раскопки культа Сумеречного Молота занимают северо-западный угол: фрагменты табличек лежат на земле, их также носят пылевихри и пустынные грохотуны. С любого культиста может упасть {item:20404}: сохраните двадцать – десять для персонажа {npc:15306} и десять позже для персонажа {npc:15194}.",
		["Tram to {zone:1455}"] = "Поезд до {zone:1455}",
		["Twilight Tablet Fragments"] = "Фрагменты Сумеречной таблички",
		["Twilight's Hammer cultists"] = "Культисты Сумеречного Молота",
		["Use the jars on slain oozes"] = "Используйте флаконы на убитых слизнюках",
		["Wait a moment for {npc:9116}"] = "Подождите немного {npc:9116}",
		["{npc:10301}'s camp"] = "Лагерь {npc:10301}",
		["{npc:10301}'s supplies"] = "Припасы {npc:10301}",
		["{npc:10667} waits in the ruined inn on the west side of Andorhal, the ruined city north of the camp. {npc:1852} guards his phylactery in the middle of the town."] = "{npc:10667} ждет в разрушенной таверне в западной части Андорала – разрушенного города к северу от лагеря. {npc:1852} охраняет свою филактерию в центре города.",
		["{npc:11803} holds the cultists' camp in the far south-west."] = "{npc:11803} удерживает лагерь культистов на дальнем юго-западе.",
		["{npc:14722}, in the {object:2096}"] = "{npc:14722} – здесь: {object:2096}",
		["{npc:15189} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15189} стоит наверху в своем здании: поднимитесь внутри, стрелка не различает этажи.",
		["{npc:15190} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15190} стоит наверху в своем здании: поднимитесь внутри, стрелка не различает этажи.",
		["{npc:15190}, upstairs beside {npc:15189}"] = "{npc:15190} – наверху, рядом с {npc:15189}",
		["{npc:1852} is a level 61 elite"] = "{npc:1852} – элитный противник 61-го уровня",
		["{npc:1855} (optional)"] = "{npc:1855} (по желанию)",
		["{npc:1855} lives in a small hut on the border river, north-east of the lumber camp. Hand in {quest:5781} if you finished it."] = "{npc:1855} живет в маленькой хижине у пограничной реки, к северо-востоку от лесопилки. Сдайте задание «{quest:5781}», если выполнили его.",
		["{npc:4155}, in the bank"] = "{npc:4155} – в банке",
		["{npc:7740} in {zone:1457}: keep it"] = "{npc:7740} ({zone:1457}): сохраните задание",
		["{npc:7740}, in the Temple of the Moon"] = "{npc:7740} – в Храме Луны",
		["{npc:8737}, at the back of the refuge"] = "{npc:8737} – в глубине лагеря",
		["{zone:1453} has no shaman trainer"] = "В городе {zone:1453} нет учителя шаманов",
} end)()
t.guides["forever/alliance/dwarf/01-dun-morogh"] = (function() return {
		["Back through the tunnel to {npc:257597}' cave above the farm."] = "Обратно через туннель к пещере {npc:257597} над фермой.",
		["Back to {npc:257597}"] = "Вернитесь: {npc:257597}",
		["Druid trainer"] = "Учитель друидов",
		["Feather Charms, from the Frostmane Novices"] = "Обереги из перьев, с новобранцев племени Мерзлогривов",
		["Firewood"] = "Дрова",
		["Flintfire's shipments lie on the cave floor, and {npc:278166} is missing somewhere inside.\nCareful: Wendigos stand close together inside the cave, so fights easily pull several at once; drawing them out one at a time with ranged attacks from outside avoids this."] = "Грузы Кремнеграна лежат на полу пещеры, а {npc:278166} пропал где-то внутри.\nОсторожно: вендиго стоят в пещере плотно, поэтому в бою легко притянуть сразу нескольких; выманивайте их по одному дальними атаками снаружи.",
		["From the {quest:2997} she gives you"] = "Из предмета {quest:2997}, который она вам дает",
		["Frostmane Troll Whelps fill the slopes south and east of {npc:786}'s camp."] = "Тролли-подростки из племени Мерзлогривов заполняют склоны к югу и востоку от лагеря {npc:786}.",
		["Iceclaw Bear Pendants, from the Frostmane Troll Whelps on the slopes above the camp"] = "Подвески медведя-ледокогтя, с троллей-подростков из племени Мерзлогривов на склонах над лагерем",
		["Level 4 spells, before Gozwin's camp"] = "Заклинания 4-го уровня, до лагеря Гозвина",
		["Rockjaw Skullthumpers, Bonesnappers and Ambushers share the quarry and the slopes north of it; the Ambushers drop the {item:268548}."] = "Головоломы, костоломы и душители из племени Каменной Челюсти населяют карьер и склоны к северу от него; душители оставляют {item:268548}.",
		["Small Crag Boars graze around {npc:714}'s camp and along the west side of the valley."] = "Малые скальные вепри пасутся вокруг лагеря {npc:714} и вдоль западной стороны долины.",
		["Snow Leopards and boars roam the snow between the ranch and the quarry. Blacksmiths: Copper Bars come from smelting {item:2770} or the trade vendors."] = "Снежные леопарды и вепри бродят по снегу между ранчо и карьером. Кузнецы: медные слитки получают выплавкой ({item:2770}) или покупают у торговцев.",
		["Subdue the voidwalker"] = "Подчините демона Бездны",
		["The Fire Spirit Stone"] = "Камень духа огня",
		["The boars"] = "Вепри",
		["The firewood lies in the snow around the frozen lake by the refuge."] = "Дрова лежат в снегу вокруг замерзшего озера у приюта.",
		["The quarry troggs"] = "Троггы карьера",
		["The troggs"] = "Троггы",
		["The troll cave"] = "Пещера троллей",
		["The tunnel"] = "Туннель",
		["The {object:269} in the basement"] = "{object:269} в подвале",
		["Use the {item:6866} on {npc:6177}"] = "Используйте {item:6866} на NPC {npc:6177}",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Раз уж вы здесь: изучите владение посохами у NPC {npc:11867} ({object:2096}, 10 серебра); у оружия ближнего боя охотника важнее всего характеристики, а у двуручного их больше всего.",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Раз уж вы здесь: изучите владение посохами у NPC {npc:11867} ({object:2096}, 10 серебра); при прокачке посох дает больше характеристик для заклинаний, чем одноручное оружие.",
		["While you're here: learn Swords from {npc:11867} ({object:2096}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "Раз уж вы здесь: изучите владение мечами у NPC {npc:11867} ({object:2096}, 10 серебра); с мечом в правой руке разбойник стабильно качается.",
		["Young wolves"] = "Молодые волки",
		["{item:13850}: the {object:176785}"] = "{item:13850}: {object:176785}",
